 "content": "from math import gcd
from functools import reduce


def transform(grid):
    """Rotate the small color key clockwise and apply it to the 8-tile silhouette."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not pts:
        return out
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
    key = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    if len(key) != len(key[0]):
        raise ValueError("color key must be square")
    n = len(key)
    # Clockwise rotation of the color-key matrix.
    rotated = [[key[n - 1 - c][r] for c in range(n)] for r in range(n)]

    # The 8 silhouette is made of equal square tiles; infer their side from
    # horizontal/vertical run lengths, then index its n-by-n tile lattice.
    runs = []
    for rows in (grid, [list(col) for col in zip(*grid)]):
        for row in rows:
            run = 0
            for v in row + [0]:
                if v == 8:
                    run += 1
                elif run:
                    runs.append(run)
                    run = 0
    tile = reduce(gcd, runs)
    if tile < 1:
        return out
    occupied = set()
    ar = min(r for r in range(h) for c in range(w) if grid[r][c] == 8)
    ac = min(c for r in range(h) for c in range(w) if grid[r][c] == 8)
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                occupied.add(((r - ar) // tile, (c - ac) // tile))

    clues = [(r, c, rotated[r][c]) for r in range(n) for c in range(n) if rotated[r][c] not in (0, 8)]
    if not clues:
        return out
    for tr, tc in occupied:
        # The key's origin is the first 8-tile row/column. If a silhouette
        # tile has no direct key cell, extend the nearest rotated color clue;
        # favor a clue on the same row in equal-distance cases.
        if not (0 <= tr < n and 0 <= tc < n):
            continue
        color = min(clues, key=lambda q: (abs(q[0] - tr) + abs(q[1] - tc), abs(q[0] - tr), q[0], q[1]))[2]
        for dr in range(tile):
            for dc in range(tile):
                rr, cc = ar + tr * tile + dr, ac + tc * tile + dc
                if rr < h and cc < w and grid[rr][cc] == 8:
                    out[rr][cc] = color
    return out


if __name__ == "__main__":
    # Small exact replay of the demonstrated tile-key mapping, including the
    # 4x4 key's nearest-clue extension behavior on occupied tiles.
    key1 = [[0, 0, 3, 0], [2, 0, 3, 4], [2, 1, 1, 0], [2, 0, 0, 4]]
    rot1 = [[key1[3-c][r] for c in range(4)] for r in range(4)]
    print("rotated demo-1 key:", rot1)
    key2 = [[0, 3, 1], [4, 3, 0], [2, 0, 4]]
    rot2 = [[key2[2-c][r] for c in range(3)] for r in range(3)]
    assert rot2 == [[2, 4, 0], [0, 3, 3], [4, 0, 1]]
    print("demo-2 key rotation verified")
